-- Inventory Stock Management System
-- Fresh PostgreSQL setup script
--
-- Run this script against an empty PostgreSQL database, for example `inventory_db`.
-- It matches the current EF Core model in backend-api/Migrations/20260907121939_InitialCreate.cs
-- and seeds sample/master data without introducing a second database design.

BEGIN;

CREATE TABLE IF NOT EXISTS "Items" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "ItemCode" character varying(50) NOT NULL,
    "ItemName" character varying(200) NOT NULL,
    "Category" character varying(100),
    "Unit" character varying(20) NOT NULL,
    "ReorderLevel" numeric(18,3) NOT NULL,
    "IsActive" boolean NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Items" PRIMARY KEY ("Id")
);

CREATE TABLE IF NOT EXISTS "Stores" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Code" character varying(50) NOT NULL,
    "Name" character varying(200) NOT NULL,
    "IsActive" boolean NOT NULL,
    CONSTRAINT "PK_Stores" PRIMARY KEY ("Id")
);

CREATE TABLE IF NOT EXISTS "StockBalances" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "StoreId" integer NOT NULL,
    "ItemId" integer NOT NULL,
    "Quantity" numeric(18,3) NOT NULL,
    CONSTRAINT "PK_StockBalances" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_StockBalances_Items_ItemId" FOREIGN KEY ("ItemId") REFERENCES "Items" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_StockBalances_Stores_StoreId" FOREIGN KEY ("StoreId") REFERENCES "Stores" ("Id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "StockTransactions" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "TransactionNo" character varying(50) NOT NULL,
    "TransactionDate" timestamp with time zone NOT NULL,
    "TransactionType" integer NOT NULL,
    "StoreId" integer NOT NULL,
    "Remarks" character varying(500),
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_StockTransactions" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_StockTransactions_Stores_StoreId" FOREIGN KEY ("StoreId") REFERENCES "Stores" ("Id") ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS "StockTransactionDetails" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "StockTransactionId" integer NOT NULL,
    "ItemId" integer NOT NULL,
    "Quantity" numeric(18,3) NOT NULL,
    "Unit" character varying(20) NOT NULL,
    "Remarks" character varying(500),
    CONSTRAINT "PK_StockTransactionDetails" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_StockTransactionDetails_Items_ItemId" FOREIGN KEY ("ItemId") REFERENCES "Items" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StockTransactionDetails_StockTransactions_StockTransactionId" FOREIGN KEY ("StockTransactionId") REFERENCES "StockTransactions" ("Id") ON DELETE CASCADE
);

CREATE UNIQUE INDEX IF NOT EXISTS "IX_Items_ItemCode" ON "Items" ("ItemCode");
CREATE INDEX IF NOT EXISTS "IX_StockBalances_ItemId" ON "StockBalances" ("ItemId");
CREATE UNIQUE INDEX IF NOT EXISTS "IX_StockBalances_StoreId_ItemId" ON "StockBalances" ("StoreId", "ItemId");
CREATE INDEX IF NOT EXISTS "IX_StockTransactionDetails_ItemId" ON "StockTransactionDetails" ("ItemId");
CREATE INDEX IF NOT EXISTS "IX_StockTransactionDetails_StockTransactionId" ON "StockTransactionDetails" ("StockTransactionId");
CREATE INDEX IF NOT EXISTS "IX_StockTransactions_StoreId_TransactionDate" ON "StockTransactions" ("StoreId", "TransactionDate");
CREATE INDEX IF NOT EXISTS "IX_StockTransactions_TransactionDate" ON "StockTransactions" ("TransactionDate");
CREATE UNIQUE INDEX IF NOT EXISTS "IX_StockTransactions_TransactionNo" ON "StockTransactions" ("TransactionNo");
CREATE UNIQUE INDEX IF NOT EXISTS "IX_Stores_Code" ON "Stores" ("Code");

-- TransactionType values used by the application:
-- 1 = Receipt
-- 2 = Issue
-- 3 = Transfer
-- 4 = Adjustment
-- 5 = OpeningBalance

INSERT INTO "Stores" ("Id", "Code", "Name", "IsActive") VALUES
    (1, 'STR-001', 'Main Warehouse', true),
    (2, 'STR-002', 'Branch Store', true);

INSERT INTO "Items" ("Id", "ItemCode", "ItemName", "Category", "Unit", "ReorderLevel", "IsActive", "CreatedAt", "UpdatedAt") VALUES
    (1, 'ITM-001', 'A4 Paper Ream', 'Stationery', 'REAM', 10.000, true, TIMESTAMPTZ '2026-09-01 00:00:00+00', TIMESTAMPTZ '2026-09-01 00:00:00+00'),
    (2, 'ITM-002', 'Ballpoint Pen Blue', 'Stationery', 'BOX', 5.000, true, TIMESTAMPTZ '2026-09-01 00:00:00+00', TIMESTAMPTZ '2026-09-01 00:00:00+00'),
    (3, 'ITM-003', 'USB Keyboard', 'IT Accessories', 'PCS', 8.000, true, TIMESTAMPTZ '2026-09-01 00:00:00+00', TIMESTAMPTZ '2026-09-01 00:00:00+00');

