    (1, 'OPEN-20260901-001', TIMESTAMPTZ '2026-09-01 00:00:00+00', 5, 1, 'Opening stock for main warehouse', TIMESTAMPTZ '2026-09-01 00:00:00+00', TIMESTAMPTZ '2026-09-01 00:00:00+00'),
