    (4, 'REC-20260905-001', TIMESTAMPTZ '2026-09-05 00:00:00+00', 1, 1, 'Additional receive', TIMESTAMPTZ '2026-09-05 00:00:00+00', TIMESTAMPTZ '2026-09-05 00:00:00+00'),
