    (6, 'OPEN-20260901-002', TIMESTAMPTZ '2026-09-01 00:00:00+00', 5, 2, 'Opening stock for branch store', TIMESTAMPTZ '2026-09-01 00:00:00+00', TIMESTAMPTZ '2026-09-01 00:00:00+00'),
    (7, 'ISS-20260904-002', TIMESTAMPTZ '2026-09-04 00:00:00+00', 2, 2, 'Branch issue', TIMESTAMPTZ '2026-09-04 00:00:00+00', TIMESTAMPTZ '2026-09-04 00:00:00+00'),
