INSERT INTO "StockTransactionDetails" ("Id", "StockTransactionId", "ItemId", "Quantity", "Unit", "Remarks") VALUES
    (1, 1, 1, 50.000, 'REAM', 'Opening quantity'),
    (2, 1, 3, 30.000, 'PCS', 'Opening quantity'),
