    (5, 3, 3, 5.000, 'PCS', 'Issued to department'),
    (6, 4, 1, 20.000, 'REAM', 'Received from supplier'),
    (7, 5, 1, 15.000, 'REAM', 'Issued to department'),
    (8, 6, 2, 60.000, 'BOX', 'Opening quantity'),
    (9, 7, 2, 12.000, 'BOX', 'Issued to branch users'),
    (10, 8, 2, 51.000, 'BOX', 'Received from supplier');

-- StockBalances are seeded to match the transaction history above.
INSERT INTO "StockBalances" ("Id", "StoreId", "ItemId", "Quantity") VALUES
    (1, 1, 1, 95.000),
    (2, 1, 3, 25.000),
    (3, 2, 2, 99.000);

SELECT setval(pg_get_serial_sequence('"Stores"', 'Id'), COALESCE((SELECT MAX("Id") FROM "Stores"), 1), true);
SELECT setval(pg_get_serial_sequence('"Items"', 'Id'), COALESCE((SELECT MAX("Id") FROM "Items"), 1), true);
SELECT setval(pg_get_serial_sequence('"StockTransactions"', 'Id'), COALESCE((SELECT MAX("Id") FROM "StockTransactions"), 1), true);
SELECT setval(pg_get_serial_sequence('"StockTransactionDetails"', 'Id'), COALESCE((SELECT MAX("Id") FROM "StockTransactionDetails"), 1), true);
SELECT setval(pg_get_serial_sequence('"StockBalances"', 'Id'), COALESCE((SELECT MAX("Id") FROM "StockBalances"), 1), true);

COMMIT;
